export type ReportPresentationCopy = typeof en;

const presentationCopies: Record<PresentationLanguage, ReportPresentationCopy> = { en, de, pl, nl, fr, es, fi };

export function getReportPresentation(language: string): ReportPresentationCopy {
  return presentationCopies[presentationLocale(language)];
}

export function presentationTextValues(language: string): string[] {
  return Object.values(getReportPresentation(language));
}

