/** Returns a localized display title while source identity remains keyed by the unchanged source ID. */
export function getLocalizedSourceTitle(id: string, canonicalTitle: string, language: string): string {
  const locale = presentationLocale(language);
  return localizePresentationValue(sourceTitles[id]?.[locale] || canonicalTitle, locale);
}
